CREATE TABLE results(id INTEGER PRIMARY KEY,name TEXT,score INTEGER);
INSERT INTO results VALUES(1,'Mira',9),(2,'Oren',9),(3,'Paz',7),(4,'Rin',5);
SELECT id,name,score,ROW_NUMBER() OVER (ORDER BY score DESC,id) AS position,DENSE_RANK() OVER (ORDER BY score DESC) AS level
FROM results
ORDER BY score DESC,id;
```
Positions are 1,2,3,4. Dense ranks are 1,1,2,3: the two scores of 9 share rank 1.

